package com.orient.ortts.demo;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.nio.*;import java.nio.file.*;import java.util.*;
/** Debug-only bounded replay of real microphone-recording fixtures through public JNI APIs. */
public final class InteractionQaActivity extends Activity {
 volatile StreamingPlayer player;volatile boolean measuring;Thread sampler;long peakPss,gap,samples;TextView view;
 long now(){return SystemClock.elapsedRealtimeNanos();}double ms(long start){return (now()-start)/1e6;}
 void save(File f,JSONObject o)throws Exception{File t=new File(f.getPath()+".tmp");Files.write(t.toPath(),o.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));if(!t.renameTo(f))throw new IOException("result rename");}
 float[] pcm(String id)throws Exception{if(!id.matches("[a-zA-Z0-9_-]+"))throw new IOException("fixture id");byte[] b=Files.readAllBytes(new File(getFilesDir(),"asr-fixtures/"+id+".f32").toPath());float[] p=new float[b.length/4];ByteBuffer.wrap(b).order(ByteOrder.LITTLE_ENDIAN).asFloatBuffer().get(p);return p;}
 JSONObject trial(JSONObject f)throws Exception{SpeechBridge.resetAsr();float[] p=pcm(f.getString("id"));String[] text={""};long start=now();for(int n=0;n<p.length;n+=3200){float[] c=Arrays.copyOfRange(p,n,Math.min(n+3200,p.length));SpeechBridge.accept(c,c.length,(t,e,s)->{if(e!=0)text[0]=t;});}SpeechBridge.finish((t,e,s)->{if(e!=0)text[0]=t;});return new JSONObject().put("id",f.getString("id")).put("language",f.getString("language")).put("text",text[0]).put("api_ms",ms(start)).put("audio_s",p.length/16000.0);}
 public void onCreate(Bundle b){super.onCreate(b);view=new TextView(this);view.setText("OrTTS 交互闭环验收");setContentView(view);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);String id=getIntent().getStringExtra("qa_id");if(!BuildConfig.DEBUG||id==null||!id.matches("[a-zA-Z0-9_-]{1,64}")||!MainActivity.busy.compareAndSet(false,true))return;MainActivity.worker.execute(()->run(id));}
 void run(String id){File dir=new File(getFilesDir(),"interaction-qa/"+id);dir.mkdirs();JSONObject result=new JSONObject();JSONArray steps=new JSONArray();measuring=true;sampler=new Thread(()->{long last=0;while(measuring){long t=now();if(last>0)gap=Math.max(gap,t-last);last=t;peakPss=Math.max(peakPss,Debug.getPss());samples++;SystemClock.sleep(25);}},"interaction-memory");sampler.start();try{
  SpeechBridge.load();result.put("capabilities",new JSONObject(SpeechBridge.capabilities()));JSONObject fixtures=new JSONObject(new String(Files.readAllBytes(new File(getFilesDir(),"asr-fixtures/FIXTURES.json").toPath()),java.nio.charset.StandardCharsets.UTF_8));JSONArray fs=fixtures.getJSONArray("trials");String path=new File(getFilesDir(),"speech-models/sensevoice-small-q8-audiocpp-v1.gguf").getPath();
  long start=now();SpeechBridge.openAsr("sense_asr",path);steps.put(new JSONObject().put("step","sense_load").put("wall_ms",ms(start)));
  JSONObject first=trial(fs.getJSONObject(0));steps.put(first);for(int i:new int[]{20,40})steps.put(trial(fs.getJSONObject(i)));
  SpeechBridge.endTask();start=now();SpeechBridge.openAsr("sense_asr",path);steps.put(new JSONObject().put("step","resident_reopen").put("wall_ms",ms(start)).put("state",new JSONObject(SpeechBridge.residency())));
  if(!first.getString("text").equals(trial(fs.getJSONObject(0)).getString("text")))throw new IOException("resident output changed");
  SpeechBridge.resetAsr();float[] input=pcm(fs.getJSONObject(0).getString("id"));for(int n=0;n<input.length;n+=3200){float[] chunk=Arrays.copyOfRange(input,n,Math.min(n+3200,input.length));SpeechBridge.accept(chunk,chunk.length,(t,e,s)->{});}long[] signal={0};Thread cancel=new Thread(()->{SystemClock.sleep(5);signal[0]=now();SpeechBridge.cancel();});cancel.start();String error="";long ended=0;try{SpeechBridge.finish((t,e,s)->{});}catch(Exception e){error=e.toString();ended=now();}cancel.join();if(!error.toLowerCase(Locale.ROOT).contains("cancel"))throw new IOException("offline cancellation not observed: "+error);
  steps.put(new JSONObject().put("step","cross_thread_cancel").put("error",error).put("latency_ms",(ended-signal[0])/1e6).put("semantics","discard after offline compute; not kernel interruption"));
  if(!first.getString("text").equals(trial(fs.getJSONObject(0)).getString("text")))throw new IOException("cancel/reset changed next request");
  SpeechBridge.close();SpeechBridge.openAsr("sense_asr",path);if(!first.getString("text").equals(trial(fs.getJSONObject(0)).getString("text")))throw new IOException("release/reload changed output");steps.put(new JSONObject().put("step","asr_reset_release_reload").put("exact",true));SpeechBridge.close();
  ModelManager manager=new ModelManager(this,s->{});File root=manager.current();if(root==null||!manager.ready("P3"))throw new IOException("existing OrTTS P3 package unavailable; no implicit download");String spoken=first.getString("text");if(spoken.trim().isEmpty())throw new IOException("empty recognized text");result.put("recognized_text",spoken).put("tts_model_id",ModelManager.manifest(root).getString("model_id")).put("acoustic_identity",ModelManager.acousticIdentity(root));
  File interrupted=new File(dir,"tts-cancelled");interrupted.mkdirs();final boolean[] callback={false};String stopped="";start=now();try(StreamingPlayer p=new StreamingPlayer(true,spoken.length())){player=p;try{NativeBridge.run(root.getPath(),"P3","female",spoken,4,20261029L,true,(x,rate)->{callback[0]=true;p.requestStop();p.onPcm(x,rate);},interrupted.getPath(),ModelManager.acousticIdentity(root));}catch(Exception e){stopped=e.toString();}}finally{player=null;}
  if(!callback[0]||stopped.isEmpty())throw new IOException("TTS callback cancellation not observed");steps.put(new JSONObject().put("step","tts_playback_cancel").put("callback",true).put("error",stopped).put("wall_ms",ms(start)));
  File recovered=new File(dir,"tts-recovered");recovered.mkdirs();try(StreamingPlayer p=new StreamingPlayer(true,spoken.length())){player=p;JSONObject report=new JSONObject(NativeBridge.run(root.getPath(),"P3","female",spoken,4,20261029L,true,p,recovered.getPath(),ModelManager.acousticIdentity(root)));p.drain();report.put("playback",p.metrics());if(!"eos".equals(report.optString("EOS"))||!report.optBoolean("callback_concat_exact")||!report.optBoolean("session_reused"))throw new IOException("TTS recovered EOS/PCM/reuse mismatch");save(new File(dir,"TTS.json"),report);steps.put(new JSONObject().put("step","tts_same_session_recovered").put("report",report));}finally{player=null;}
  NativeBridge.release();SpeechBridge.openAsr("sense_asr",path);if(!first.getString("text").equals(trial(fs.getJSONObject(0)).getString("text")))throw new IOException("TTS to ASR output mismatch");steps.put(new JSONObject().put("step","tts_to_asr_recovered").put("exact",true));
  result.put("ok",true);
 }catch(Throwable e){try{result.put("ok",false).put("error",e.toString());StringWriter sw=new StringWriter();e.printStackTrace(new PrintWriter(sw));result.put("trace",sw.toString());}catch(Exception ignored){}}
 finally{measuring=false;try{sampler.join(2000);SpeechBridge.close();NativeBridge.release();result.put("steps",steps).put("peak_app_PSS_KiB_sampled",peakPss).put("memory_samples",samples).put("sampling_max_gap_ms",gap/1e6).put("input","recorded ASCEND human PCM; not live microphone");save(new File(dir,"RESULT.json"),result);}catch(Exception ignored){}MainActivity.busy.set(false);runOnUiThread(()->view.setText(result.toString()));}}
 protected void onDestroy(){StreamingPlayer p=player;if(p!=null)p.requestStop();try{SpeechBridge.cancel();}catch(Throwable ignored){}super.onDestroy();}
}
